 static Map<String,Object> preferences(SharedPreferences prefs){Map<String,Object> result=new HashMap<>();for(Map.Entry<String,?> entry:prefs.getAll().entrySet())result.put(entry.getKey(),entry.getValue() instanceof Set?new HashSet<>((Set<?>)entry.getValue()):entry.getValue());return result;}
 @SuppressWarnings("unchecked") static void restore(SharedPreferences prefs,Map<String,Object> values)throws Exception{SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,Object> entry:values.entrySet()){String key=entry.getKey();Object value=entry.getValue();if(value instanceof String)e.putString(key,(String)value);else if(value instanceof Boolean)e.putBoolean(key,(Boolean)value);else if(value instanceof Integer)e.putInt(key,(Integer)value);else if(value instanceof Long)e.putLong(key,(Long)value);else if(value instanceof Float)e.putFloat(key,(Float)value);else if(value instanceof Set)e.putStringSet(key,(Set<String>)value);else throw new Exception("Unknown preference type: "+key);}if(!e.commit())throw new Exception("Could not restore test preferences");}
