 /** Attached native buttons must keep their optical material flat through press/release,
  * while retaining ripple feedback, accessibility and exactly one click callback. */
 static void flatButtonStates(Instrumentation test,MainActivity host,String mode)throws Exception{
  final SheetDialog[] sheet={null};final List<Button> buttons=new ArrayList<>();final AtomicInteger clicks=new AtomicInteger();
  try{
   main(test,()->{LinearLayout content=Modern.column(host);content.addView(Glass.text(host,"Acciones nativas",20,true));for(String label:new String[]{"Más opciones","Cancelar","Guardar prueba"}){Button button=Glass.button(host,label);button.setOnClickListener(v->clicks.incrementAndGet());content.addView(button);buttons.add(button);}sheet[0]=new SheetDialog(host,content);sheet[0].show();});settled(test);
   main(test,()->{for(Button button:buttons){yes(button.isAttachedToWindow()&&button.getElevation()==0&&button.getTranslationZ()==0,"Attached action must retain zero shadow in "+mode+": "+button.getText());yes(button.getBackground() instanceof android.graphics.drawable.RippleDrawable&&button.isClickable()&&"android.widget.Button".contentEquals(button.getAccessibilityClassName()),"Flat actions must retain native ripple, click and accessibility behavior in "+mode);button.setPressed(true);}});settled(test);
   main(test,()->{for(Button button:buttons){yes(button.isPressed()&&button.getElevation()==0&&button.getTranslationZ()==0,"Pressing an attached action must not raise its native shadow in "+mode);button.setPressed(false);}yes(clicks.get()==0,"Pressed-state feedback must not execute action callbacks");});settled(test);
   main(test,()->{for(Button button:buttons){yes(!button.isPressed()&&button.getElevation()==0&&button.getTranslationZ()==0,"Released action must remain flat in "+mode);button.performClick();}yes(clicks.get()==buttons.size(),"Each native action click must invoke its callback exactly once");});
  }finally{main(test,()->{if(sheet[0]!=null)sheet[0].dismiss();});test.waitForIdleSync();}
 }
 static void gesture(SnapCarousel carousel,float fractionX,float fractionY,int duration,boolean cancel,boolean child){long start=SystemClock.uptimeMillis();float x=carousel.getWidth()*.82f,y=carousel.getHeight()*.55f;if(child){View first=((ViewGroup)carousel.getChildAt(0)).getChildAt(0);x=Math.min(first.getWidth()*.75f,carousel.getWidth()*.82f);}float dx=carousel.getWidth()*fractionX,dy=carousel.getHeight()*fractionY;MotionEvent down=MotionEvent.obtain(start,start,MotionEvent.ACTION_DOWN,x,y,0);carousel.dispatchTouchEvent(down);down.recycle();for(int i=1;i<=6;i++){MotionEvent move=MotionEvent.obtain(start,start+i*duration/7,MotionEvent.ACTION_MOVE,x+dx*i/6,y+dy*i/6,0);carousel.dispatchTouchEvent(move);move.recycle();}MotionEvent end=MotionEvent.obtain(start,start+duration,cancel?MotionEvent.ACTION_CANCEL:MotionEvent.ACTION_UP,x+dx,y+dy,0);carousel.dispatchTouchEvent(end);end.recycle();}
 static boolean imeVisible(View view){if(Build.VERSION.SDK_INT>=30&&view.getRootWindowInsets()!=null)return view.getRootWindowInsets().isVisible(WindowInsets.Type.ime());Rect visible=new Rect();view.getWindowVisibleDisplayFrame(visible);return view.getResources().getDisplayMetrics().heightPixels-visible.bottom>Glass.dp(view.getContext(),120);}
 static void waitImeVisible(Instrumentation test,View view)throws Exception{long deadline=SystemClock.uptimeMillis()+5000;final boolean[] visible={false};do{test.waitForIdleSync();main(test,()->visible[0]=imeVisible(view));if(visible[0])return;Thread.sleep(100);}while(SystemClock.uptimeMillis()<deadline);}
 static void reachable(Instrumentation test,SheetDialog sheet,String label)throws Exception{final java.util.List<android.view.accessibility.AccessibilityWindowInfo> windows=test.getUiAutomation().getWindows();main(test,()->{Button action=null;for(Button b:views(sheet.footer,Button.class))if(b.getText().toString().equals(label))action=b;yes(action!=null,"The save action must exist in the fixed footer");Rect frame=new Rect(),visible=new Rect();sheet.layout.getWindowVisibleDisplayFrame(frame);if(Build.VERSION.SDK_INT>=30){WindowMetrics metrics=sheet.getContext().getSystemService(WindowManager.class).getCurrentWindowMetrics();Rect bounds=metrics.getBounds();android.graphics.Insets bars=metrics.getWindowInsets().getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());android.graphics.Insets ime=sheet.layout.getRootWindowInsets()!=null&&imeVisible(sheet.layout)?sheet.layout.getRootWindowInsets().getInsets(WindowInsets.Type.ime()):android.graphics.Insets.NONE;frame.set(bounds.left+Math.max(bars.left,ime.left),bounds.top+Math.max(bars.top,ime.top),bounds.right-Math.max(bars.right,ime.right),bounds.bottom-Math.max(bars.bottom,ime.bottom));}String keyboardBounds="none";for(android.view.accessibility.AccessibilityWindowInfo window:windows)if(window.getType()==android.view.accessibility.AccessibilityWindowInfo.TYPE_INPUT_METHOD){Rect keyboard=new Rect();window.getBoundsInScreen(keyboard);keyboardBounds=keyboard.toString();if(!keyboard.isEmpty()&&keyboard.bottom>=frame.bottom&&keyboard.width()>frame.width()/2)frame.bottom=Math.min(frame.bottom,keyboard.top);}boolean onScreen=action.getGlobalVisibleRect(visible);int[] position=new int[2];action.getLocationOnScreen(position);Bundle bounds=new Bundle();bounds.putString("reachabilityBounds","frame="+frame+" action="+position[0]+","+position[1]+" size="+action.getWidth()+","+action.getHeight()+" visible="+visible+" sheetHeight="+sheet.layout.getHeight()+" ime="+imeVisible(sheet.layout)+" keyboardWindow="+keyboardBounds);test.sendStatus(0,bounds);yes(onScreen&&visible.height()>=action.getHeight()-2,"The save action must be fully visible");yes(position[1]+action.getHeight()<=frame.bottom+2,"The save action must stay above the keyboard/system bars");yes(position[0]>=frame.left&&position[0]+action.getWidth()<=frame.right,"The save action must fit the available width");yes(sheet.layout.getHeight()<=frame.height(),"The form sheet must remain bounded by the visible window");});}
 static AccessibilityNodeInfo node(Instrumentation test,String text)throws Exception{AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root==null)throw new Exception("Active accessibility window is missing");return exact(root,text);}
 static AccessibilityNodeInfo exact(AccessibilityNodeInfo root,String text){if(text.contentEquals(root.getText()==null?"":root.getText()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo child=root.getChild(i);if(child==null)continue;AccessibilityNodeInfo match=exact(child,text);if(match!=null)return match;}return null;}
 static AccessibilityNodeInfo hint(AccessibilityNodeInfo root,String wanted){if(root.isEditable()&&(wanted.contentEquals(root.getHintText()==null?"":root.getHintText())||wanted.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo child=root.getChild(i);if(child!=null){AccessibilityNodeInfo match=hint(child,wanted);if(match!=null)return match;}}return null;}
 static AccessibilityNodeInfo dateNode(AccessibilityNodeInfo root){if(root==null)return null;String description=root.getContentDescription()==null?"":root.getContentDescription().toString();if(description.startsWith("Fecha.")&&"android.widget.EditText".contentEquals(root.getClassName()==null?"":root.getClassName()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo child=root.getChild(i);if(child!=null){AccessibilityNodeInfo match=dateNode(child);if(match!=null)return match;}}return null;}
 static void setText(Instrumentation test,String label,String value)throws Exception{AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();yes(root!=null,"The debt form must be an active native window");AccessibilityNodeInfo field=hint(root,label);yes(field!=null,"The real debt field must be available: "+label);Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);yes(field.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args),"Native debt field must accept entered text");test.waitForIdleSync();}
 static void assertAccessibleAction(Instrumentation test,String label,MainActivity a,String why)throws Exception{settled(test);AccessibilityNodeInfo action=node(test,label);yes(action!=null&&action.isVisibleToUser()&&action.isEnabled(),why);Rect bounds=new Rect();action.getBoundsInScreen(bounds);yes(bounds.width()>a.dp(40)&&bounds.height()>=a.dp(44),why+" with a usable touch target");}
 static void cancelActive(Instrumentation test)throws Exception{AccessibilityNodeInfo cancel=node(test,"Cancelar");yes(cancel!=null&&cancel.performAction(AccessibilityNodeInfo.ACTION_CLICK),"A financial form must provide a working cancel action");test.waitForIdleSync();settled(test);}
 static void datePicker(Instrumentation test,Context c,String mode)throws Exception{AccessibilityNodeInfo more=node(test,"Más opciones");yes(more!=null&&more.performAction(AccessibilityNodeInfo.ACTION_CLICK),"The real expense form must expose its date options");settled(test);AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow(),date=dateNode(root);yes(date!=null,"The real expense date must be accessible");date.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.getId());settled(test);root=test.getUiAutomation().getRootInActiveWindow();date=dateNode(root);yes(date!=null&&date.performAction(AccessibilityNodeInfo.ACTION_CLICK),"The real expense date must open its native picker");settled(test);yes(node(test,Ledger.today().substring(0,4))!=null,"The native date picker must show the selected year");shot(test,c,"visual-date-picker-"+mode);test.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);settled(test);yes(node(test,"Guardar movimiento")!=null,"Closing the picker must preserve the unsaved financial form");}
 /** No Activity, rotation, window blur or GPU readback; checks the native chart geometry independently. */
 static int charts(Instrumentation test,Context c)throws Exception{
  checks=0;SharedPreferences settings=NativeStore.settings(c);Map<String,Object> before=preferences(settings);status(test,"begin independent native chart checks");
  try{for(String mode:new String[]{"dark","light"}){
   settings.edit().putString("appearance",mode).putString("palette","prisma").commit();status(test,"before native chart geometry "+mode);
   main(test,()->{
    long[] values={40,30,20,10};DonutChart donut=new DonutChart(c,values,new int[]{Glass.MINT,Glass.VIOLET,Glass.BLUE,Glass.CORAL});values[0]=99;yes(donut.values[0]==40&&donut.total==100,"Donut must defensively retain the actual category values");donut.layout(0,0,Glass.dp(c,180),Glass.dp(c,180));float sum=0;for(int i=0;i<donut.sweeps.length;i++){sum+=donut.sweeps[i];yes(Math.abs(donut.sweeps[i]-360f*donut.values[i]/donut.total)<.001f,"Donut share must match the accounting ratio");if(i>0)yes(Math.abs(donut.starts[i]-donut.starts[i-1]-donut.sweeps[i-1])<.001f,"Adjacent donut categories must not invent gaps");}yes(donut.starts[0]==-90&&Math.abs(donut.starts[3]+donut.sweeps[3]-270)<.001f,"Donut cached angles must close exactly at the first category boundary");yes(Math.abs(sum-360)<.001f,"Nonzero donut shares must cover exactly one circle");chartBitmap(c,donut,"visual-graph-donut-"+mode);
    DonutChart zero=new DonutChart(c,new long[]{0,0},new int[]{Glass.MINT,Glass.CORAL});zero.layout(0,0,Glass.dp(c,120),Glass.dp(c,120));yes(zero.total==0&&zero.sweeps[0]==0&&zero.sweeps[1]==0,"Empty data must not invent an expense slice");
    long[] points={12000,2500,18000,4000};FlowChart flow=new FlowChart(c,points,Glass.primary(c),new String[]{"1 oct · $12.000","2 oct · $2.500","3 oct · $18.000","4 oct · $4.000"});points[0]=0;flow.layout(0,0,Glass.dp(c,360),Glass.dp(c,190));yes(flow.values[0]==12000,"Flow chart must retain the observed values");yes(Math.abs(flow.ys[2]-flow.top)<.01f&&Math.abs(flow.ys[1]-flow.bottom)<.01f,"Flow chart extrema must use the full observed scale");float distance=0;for(int i=1;i<flow.xs.length;i++){yes(flow.xs[i]>flow.xs[i-1],"Observed flow points must preserve their order");distance+=Math.hypot(flow.xs[i]-flow.xs[i-1],flow.ys[i]-flow.ys[i-1]);}for(int i=0;i<flow.xs.length;i++)yes(flow.nearest(flow.xs[i])==i,"Nearest-point selection must identify the exact cached x coordinate");yes(flow.nearest(flow.xs[0]*.25f+flow.xs[1]*.75f)==1,"Nearest-point selection must use proximity rather than truncating into a bucket");yes(Math.abs(new PathMeasure(flow.line,false).getLength()-distance)<.2f,"Flow path must join observed points without fabricating a smoothed trajectory");
    touchPoint(flow,flow.xs[2],flow.ys[2]);yes(flow.selected==2,"Touch must identify the selected observed point");flow.select(0,false);yes(flow.performAccessibilityAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null)&&flow.selected==1,"Chart points must be selectable through accessibility");int selected=flow.selected;long time=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(time,time,0,flow.xs[1],flow.ys[1],0),move=MotionEvent.obtain(time,time+100,2,flow.xs[1],flow.ys[1]+Glass.dp(c,80),0),up=MotionEvent.obtain(time,time+200,1,flow.xs[1],flow.ys[1]+Glass.dp(c,80),0);flow.onTouchEvent(down);flow.onTouchEvent(move);flow.onTouchEvent(up);down.recycle();move.recycle();up.recycle();yes(flow.selected==selected,"A vertical scrolling gesture must not change the chart selection");chartBitmap(c,flow,"visual-graph-flow-"+mode);
    FlowChart flat=new FlowChart(c,new long[]{2500,2500,2500},Glass.primary(c));flat.layout(0,0,Glass.dp(c,200),Glass.dp(c,130));yes(Float.isFinite(flat.ys[0])&&flat.ys[0]==flat.ys[1]&&flat.ys[1]==flat.ys[2],"Equal amounts must produce a finite, flat chart");FlowChart empty=new FlowChart(c,new long[0],Glass.primary(c));empty.layout(0,0,Glass.dp(c,200),Glass.dp(c,130));chartBitmap(c,empty,"visual-graph-empty-"+mode);
   });status(test,"after native chart geometry "+mode);
  }
   status(test,"before software dock lens bitmap checks");settings.edit().putInt("glassIntensity",1).commit();
   main(test,()->{
    int w=96,h=32;int[] stripes=new int[w*h];for(int y=0;y<h;y++)Arrays.fill(stripes,y*w,(y+1)*w,y%4<2?0xffeeb4e6:0xff2c5a2d);
    Bitmap source=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);source.setPixels(stripes,0,w,0,0,w,h);DockLens lens=new DockLens(c);Bitmap frame=lens.render(source);int[] refracted=new int[w*h],untouched=new int[w*h];frame.getPixels(refracted,0,w,0,0,w,h);source.getPixels(untouched,0,w,0,0,w,h);yes(Arrays.equals(stripes,untouched),"Software lens must not change the captured source");yes(frame.getConfig()==Bitmap.Config.ARGB_8888&&frame.getWidth()==w&&frame.getHeight()==h,"Software lens must produce an exact-sized CPU bitmap");
    java.lang.reflect.Field geometry=DockLens.class.getDeclaredField("sampleBase"),scratch=DockLens.class.getDeclaredField("horizontal");geometry.setAccessible(true);scratch.setAccessible(true);Object mapBefore=geometry.get(lens),scratchBefore=scratch.get(lens);yes(lens.render(source)==frame&&geometry.get(lens)==mapBefore&&scratch.get(lens)==scratchBefore,"Stable bounds must reuse output, geometry and filtering storage");int[] rerendered=new int[w*h];frame.getPixels(rerendered,0,w,0,0,w,h);yes(Arrays.equals(refracted,rerendered),"Software lens must render the same source deterministically");
    int[] blurOnly=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int red=0,green=0,blue=0;for(int offset=-1;offset<=1;offset++){int colour=stripes[Math.max(0,Math.min(h-1,y+offset))*w+x];red+=colour>>>16&255;green+=colour>>>8&255;blue+=colour&255;}blurOnly[y*w+x]=0xff000000|(red+1)/3<<16|(green+1)/3<<8|(blue+1)/3;}
    boolean actualRefraction=false;for(int y=1;y<9;y++){int at=y*w+w/2;if((refracted[at]>>>24)==255&&(refracted[at]&0xffffff)!=(blurOnly[at]&0xffffff))actualRefraction=true;}yes(actualRefraction,"A real sampled bevel must differ from blur-only pixels near the straight border");yes(refracted[16*w+w/2]==blurOnly[16*w+w/2],"The center must match the filtered background without a fabricated lens warp");yes((refracted[0]>>>24)==0,"Rounded glass corners must mask pixels outside the lens");
    File qa=new File(c.getExternalFilesDir(null),"qa");qa.mkdirs();Bitmap blurred=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);blurred.setPixels(blurOnly,0,w,0,0,w,h);Bitmap[] images={source,blurred,frame};String[] names={"visual-dock-lens-source","visual-dock-lens-blur-only","visual-dock-lens-refracted"};for(int i=0;i<images.length;i++)try(FileOutputStream out=new FileOutputStream(new File(qa,names[i]+".png"))){yes(images[i].compress(Bitmap.CompressFormat.PNG,100,out),"Software lens evidence must be capturable without GPU readback");}
    source.eraseColor(0xffddbbcd);Bitmap changed=lens.render(source);yes(changed==frame&&changed.getPixel(w/2,h/2)==0xffddbbcd,"An updated backdrop must refresh the same output bitmap");int[] uniform=new int[w*h];changed.getPixels(uniform,0,w,0,0,w,h);
    // At this fixture's maximum radius (16), x=0/95 are curved endcaps, even
    // on the middle row. Their pixel centres lie slightly inside the AA band
    // and correctly have alpha 253. Test genuinely straight top/bottom edges.
    for(int x=16;x<w-16;x++){yes(uniform[x]==0xffddbbcd,"The straight top bevel must preserve full opacity and colour");yes(uniform[(h-1)*w+x]==0xffddbbcd,"The straight bottom bevel must preserve full opacity and colour");}for(int x=1;x<w-1;x++)yes(uniform[16*w+x]==0xffddbbcd,"The interior across both rounded ends must not contain a dark seam");yes((uniform[16*w]>>>24)>=252&&(uniform[16*w+w-1]>>>24)>=252,"Outer endcap antialiasing must stay within its narrow edge band");for(int value:uniform)if((value>>>24)>128)yes(Math.abs((value>>>16&255)-221)<=2&&Math.abs((value>>>8&255)-187)<=2&&Math.abs((value&255)-205)<=2,"Rounded edges must preserve uniform colour within Bitmap premultiplication rounding");
    settings.edit().putInt("glassIntensity",2).commit();source.setPixels(stripes,0,w,0,0,w,h);Bitmap strong=lens.render(source);yes(strong==frame&&geometry.get(lens)==mapBefore,"Intensity changes must refresh the optical map without reallocating bounds");int[] stronger=new int[w*h];strong.getPixels(stronger,0,w,0,0,w,h);yes(!Arrays.equals(stronger,refracted),"The stronger material must change blur and bevel strength");
    settings.edit().putInt("glassIntensity",0).commit();Bitmap plain=lens.render(source);int[] identity=new int[w*h];plain.getPixels(identity,0,w,0,0,w,h);yes(Arrays.equals(identity,stripes),"Disabling glass must copy the source exactly");Bitmap copy=DockLens.render(c,source);yes(copy!=plain&&copy.getPixel(0,0)==stripes[0],"Static rendering must return an independently owned bitmap");lens.release();yes(!frame.isRecycled()&&frame.getPixel(0,0)==stripes[0],"Releasing a lens must not recycle a frame potentially used by RenderThread");yes(lens.render(source)!=frame,"The next render after release must safely recreate its storage");
    Bitmap tiny=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);tiny.eraseColor(0xff90abcd);settings.edit().putInt("glassIntensity",1).commit();yes(lens.render(tiny).getPixel(0,0)==0xff90abcd,"A one-pixel backdrop must remain valid without sampling outside its storage");lens.release();tiny.recycle();source.recycle();blurred.recycle();copy.recycle();
   });status(test,"after software dock lens bitmap checks");
  }finally{restore(settings,before);yes(preferences(settings).equals(before),"Independent chart checks must restore all appearance preferences");}
  return checks;
 }
 static void touchPoint(FlowChart chart,float x,float y){long time=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(time,time+60,MotionEvent.ACTION_UP,x,y,0);chart.onTouchEvent(down);chart.onTouchEvent(up);down.recycle();up.recycle();}
 static void chartBitmap(Context c,View view,String name)throws Exception{Bitmap image=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(image));if(!(view instanceof FlowChart&&((FlowChart)view).values.length==0)){int drawn=0;for(int y=0;y<image.getHeight();y+=8)for(int x=0;x<image.getWidth();x+=8)if((image.getPixel(x,y)>>>24)>0)drawn++;yes(drawn>10,"Native chart must render visible pixels: "+name);}File folder=new File(c.getExternalFilesDir(null),"qa");folder.mkdirs();try(FileOutputStream output=new FileOutputStream(new File(folder,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,output);}image.recycle();}
